<?php defined('BASEPATH') or exit('No direct script access allowed');
$company_page_title='Equipe da empresa';require APPPATH.'views/admin/companies/layout_head.php';
$esc=static fn($value)=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($query='')=>CompanyRequestScope::adminUrl($this,'company_staff'.$query);
$hidden=function(string $action)use($esc,$company_staff_csrf){foreach(['action'=>$action,'company_staff_csrf'=>$company_staff_csrf,'request_key'=>bin2hex(random_bytes(32))] as$key=>$value){echo '<input type="hidden" name="'.$esc($key).'" value="'.$esc($value).'">';}};
$permissions=function(array $selected,string $group)use($resources,$esc){?><details><summary>Permissões nesta empresa</summary><p>O vínculo permite selecionar a empresa. Cada recurso exige a permissão indicada. Uma rota legada bloqueada continua indisponível.</p><div class="company-settings-grid"><?php foreach($resources as$feature=>$definition){?><fieldset><legend><?= $esc($definition['name']); ?></legend><?php foreach($definition['capabilities'] as$cap=>$label){$id=$group.'-'.$feature.'-'.$cap;?><label for="<?= $esc($id); ?>"><input type="checkbox" id="<?= $esc($id); ?>" name="grants[<?= $esc($feature); ?>][]" value="<?= $esc($cap); ?>" <?= in_array($cap,$selected[$feature]??[],true)?'checked':''; ?>> <?= $esc($label); ?></label><?php }?></fieldset><?php }?></div></details><?php };
$fields=function(array $values,string $group,bool $password=false)use($esc){foreach(['firstname'=>['Nome',50],'lastname'=>['Sobrenome',50],'email'=>['E-mail de acesso',100],'phonenumber'=>['Telefone',30]] as$field=>[$label,$limit]){?><label for="<?= $group.'-'.$field; ?>"><?= $label; ?></label><input class="form-control" id="<?= $group.'-'.$field; ?>" name="profile[<?= $field; ?>]" type="<?= $field==='email'?'email':'text'; ?>" maxlength="<?= $limit; ?>" value="<?= $esc($values[$field]??''); ?>" <?= $field==='phonenumber'?'':'required'; ?>><?php }if($password){?><label for="<?= $group; ?>-password">Senha inicial</label><input class="form-control" id="<?= $group; ?>-password" type="password" name="profile[password]" minlength="12" maxlength="128" autocomplete="new-password" required><p>De 12 a 128 caracteres. A identidade é criada sem administração global. Esta tela não envia senha ou convite por e-mail.</p><?php }};
?>
<section class="company-settings-card"><h1>Equipe da empresa</h1><p>Gerencie apenas os vínculos e permissões da empresa ativa. O login pode ser compartilhado entre empresas; dados pessoais compartilhados exigem autoridade sobre a identidade.</p>
<?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir a equipe</a></p><?php }?>
<?php if($detail){?><h2><?= $esc($detail['firstname'].' '.$detail['lastname']); ?></h2><p><?= $esc($detail['email']); ?> · <?= (int)$detail['active']===1?'Identidade ativa':'Identidade desativada'; ?></p>
<?php if($detail['master']){?><p class="alert alert-info">Master já reconhecido da instalação. Sua identidade e o acesso automático às empresas são preservados; não é necessária nova habilitação.</p><?php }?>
<?php if($capabilities['edit']){echo form_open($url(),['id'=>'company-staff-update']);$hidden('update');?><input type="hidden" name="staff_id" value="<?= (int)$detail['staffid']; ?>"><input type="hidden" name="revision" value="<?= $esc($detail['revision']); ?>">
<?php if($detail['profile_editable']){$fields($detail,'edit');}else{?><p>Esta identidade tem vínculos ou autoridade fora desta empresa. Somente o master pode alterar nome, e-mail ou telefone; as permissões desta empresa podem ser gerenciadas abaixo.</p><?php }?>
<?php if(!$detail['master']){$permissions($detail['grants'],'edit');}?><label><input type="checkbox" name="make_default" value="1" <?= $detail['default_current']?'checked':''; ?>> Definir esta empresa como padrão</label><p>Desmarcar preserva a preferência atual. O próprio colaborador pode limpar sua preferência no perfil pessoal.</p><button type="submit">Salvar perfil e vínculo da empresa</button><?= form_close(); }?>
<?php if($capabilities['delete']&&!$detail['master']&&(int)$detail['staffid']!==$actor){echo form_open($url(),['id'=>'company-staff-revoke']);$hidden('revoke');?><input type="hidden" name="staff_id" value="<?= (int)$detail['staffid']; ?>"><input type="hidden" name="revision" value="<?= $esc($detail['revision']); ?>"><p>Revogar remove apenas o vínculo desta empresa e suas permissões. A identidade, os vínculos de outras empresas e o histórico permanecem.</p><button type="submit">Revogar vínculo desta empresa</button><?= form_close(); }?><p><a href="<?= $esc($url()); ?>">Voltar à equipe</a></p><?php }?>
<h2>Colaboradores vinculados</h2><form method="get" action="<?= $esc($url()); ?>"><label for="staff-search">Buscar nome ou e-mail nesta empresa</label><input id="staff-search" class="form-control" name="search" maxlength="100" value="<?= $esc($search); ?>"><button type="submit">Buscar</button></form>
<div class="table-responsive"><table class="table"><thead><tr><th>Colaborador</th><th>E-mail</th><th>Identidade</th></tr></thead><tbody><?php foreach($directory['items'] as$row){?><tr><td><a href="<?= $esc($url('?staff='.(int)$row['staffid'])); ?>"><?= $esc($row['firstname'].' '.$row['lastname']); ?></a></td><td><?= $esc($row['email']); ?></td><td><?= (int)$row['active']===1?'Ativa':'Desativada'; ?></td></tr><?php }?></tbody></table></div><?php if($directory['next']!==null){?><a href="<?= $esc($url('?after='.$directory['next'].'&search='.rawurlencode($search))); ?>">Próxima página</a><?php }?>
<?php if($capabilities['create']){?><h2>Criar colaborador para esta empresa</h2><?= form_open($url(),['id'=>'company-staff-create']);$hidden('create');$fields([],'new',true);$permissions([],'new');?><label><input type="checkbox" name="make_default" value="1" checked> Definir esta empresa como padrão</label><button type="submit">Criar identidade e vínculo</button><?= form_close(); ?>
<h2>Vincular identidade existente</h2><p>Informe o e-mail exato de uma identidade ativa. Nome, senha, permissões globais e acessos das outras empresas serão preservados.</p><?= form_open($url(),['id'=>'company-staff-link']);$hidden('link');?><label for="existing-email">E-mail exato</label><input id="existing-email" class="form-control" name="existing_email" type="email" maxlength="100" required><?php $permissions([],'link');?><label><input type="checkbox" name="make_default" value="1"> Tornar esta empresa padrão explicitamente</label><button type="submit">Vincular identidade existente</button><?= form_close(); }?>
</section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
